const TEST_PAGE="<!doctype html><html lang=\"fa\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"color-scheme\" content=\"light dark\"><title>آزمایش پرونده کاندیداتوری</title><style>:root{font-family:Tahoma,Arial,sans-serif;color-scheme:light dark}body{margin:0;padding:24px 14px;background:var(--tg-theme-bg-color,#f5f6f8);color:var(--tg-theme-text-color,#172536)}main{max-width:530px;margin:auto}h1{font-size:21px}p{line-height:1.9}[hidden]{display:none!important}form{display:grid;gap:13px}label{display:grid;gap:6px;font-weight:bold;font-size:14px}input,textarea,select,button{font:inherit;box-sizing:border-box;min-height:46px;border-radius:12px;border:1px solid #96a3b2;padding:10px;background:var(--tg-theme-secondary-bg-color,#fff);color:var(--tg-theme-text-color,#172536);width:100%}textarea{min-height:95px}button{background:#24554c;color:#fff;font-weight:bold;border:0}button:disabled{opacity:.55}#msg{padding:14px;border-radius:10px;background:var(--tg-theme-secondary-bg-color,#fff);overflow-wrap:anywhere}small{opacity:.7}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #c5a56c} .steps{display:flex;gap:8px;justify-content:space-between;margin:14px 0 18px;font-size:13px}.steps span{border-radius:20px;padding:9px 12px;background:var(--tg-theme-secondary-bg-color,#e8edea)}.steps span.active{background:#24554c;color:white}.modules{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.modules button{min-height:80px}.secondary{background:transparent;color:var(--tg-theme-text-color,#172536);border:1px solid #6d817c}.panel{display:grid;gap:12px}.panel h2{font-size:18px}.panel p{line-height:1.8}#summary{white-space:pre-wrap;background:var(--tg-theme-secondary-bg-color,#fff);padding:14px;border-radius:12px}.quiz-card{border:1px solid #96a3b2;border-radius:12px;padding:12px;margin:10px 0;overflow-wrap:anywhere}.quiz-option{display:flex;align-items:flex-start;gap:10px;padding:9px 4px;font-weight:normal}.quiz-option input{min-height:unset;width:auto;flex:0 0 auto;margin-top:5px}#quiz-questions fieldset{max-width:100%;overflow-wrap:anywhere}#quiz-feedback a{display:inline-block;padding:8px 0}.progress-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.progress-card,.progress-bar-card{border:1px solid #96a3b2;border-radius:12px;padding:12px;min-width:0;overflow-wrap:anywhere}.progress-number{font-size:21px;font-weight:700;padding:8px 0}.progress-bar-card{display:grid;gap:8px}.progress-bar-card progress{width:100%;height:18px;accent-color:#24554c}#progress-export{min-height:170px;font-size:12px;direction:rtl}.progress-card small{display:block}@media(max-width:340px){.progress-cards{grid-template-columns:1fr}}@media print {\n@page{size:A4;margin:14mm}\nhtml,body{background:#fff!important;color:#182c35!important}\nbody *{visibility:hidden!important}\n#progress-print,#progress-print *{visibility:visible!important}\n#progress-print{display:block!important;position:absolute!important;inset:0 auto auto 0!important;width:100%!important;max-width:none!important;min-height:auto!important;margin:0!important;padding:0!important;background:#fff!important;color:#182c35!important;box-shadow:none!important;direction:rtl!important;font-family:Tahoma,Arial,sans-serif!important}\n#progress-print .print-page{border:0!important}\n#progress-print .print-grid{display:grid!important;grid-template-columns:1fr 1fr!important;gap:10px!important}\n#progress-print .print-card,#progress-print .print-section{break-inside:avoid;page-break-inside:avoid;border:1px solid #d2dce2!important;border-radius:9px!important;padding:12px!important;margin:0 0 10px!important}\n#progress-print .print-footer{border-top:1px solid #d2dce2!important;padding-top:8px!important;font-size:10px!important}\n#progress-print h1{font-size:21px!important;margin:0 0 10px!important}\n#progress-print h2{font-size:14px!important;margin:0 0 8px!important}\n#progress-print p,#progress-print span,#progress-print strong{font-size:11px!important;line-height:1.9!important}\n#progress-print .print-value{font-size:22px!important;font-weight:bold!important;display:block!important}\n#progress-print progress{accent-color:#24554c!important;width:100%!important}\n}\n.progress-export-tools{display:grid;gap:8px}\n.print-page{direction:rtl;line-height:1.8;color:#182c35;background:#fff}\n.print-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:14px 0}\n.print-card,.print-section{border:1px solid #d2dce2;border-radius:10px;padding:13px;overflow-wrap:anywhere}\n.print-card h2,.print-section h2{margin:0 0 8px;font-size:14px}\n.print-card .print-value{font-size:22px;font-weight:bold;display:block}\n.print-header{border-bottom:2px solid #24554c;padding:0 0 14px}\n.print-header h1{margin:0 0 6px}\n.print-footer{font-size:11px;color:#556a72;margin-top:18px;border-top:1px solid #d2dce2;padding-top:12px}\n@media(max-width:340px){.print-grid{grid-template-columns:1fr}}\n.studio-card{border:1px solid #96a3b2;border-radius:12px;padding:12px;margin:10px 0;overflow-wrap:anywhere;display:grid;gap:7px}.studio-card p{white-space:pre-wrap;overflow-wrap:anywhere}.studio-card button{min-width:0}#studio-form{gap:12px}#studio-body{min-height:220px}.membership-plans{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.membership-plans article,.membership-card{border:1px solid #96a3b2;border-radius:12px;padding:12px;margin:9px 0;overflow-wrap:anywhere}.membership-card{display:grid;gap:7px}.membership-card button{min-width:0}.membership-plans small{display:block}#membership-admin{border:1px solid #96a3b2;border-radius:12px;padding:10px}@media(max-width:340px){.membership-plans{grid-template-columns:1fr}}</style></head><body><main><h1>پرونده آزمایشی کاندیداتوری</h1><p>این صفحه فقط برای آزمایش امن ثبت و ویرایش پروفایل است و به اطلاعات نسخه اصلی دسترسی ندارد.</p><div class=\"steps\" id=\"steps\" hidden><span data-step=\"1\" class=\"active\">۱. پرونده</span><span data-step=\"2\">۲. بررسی</span><span data-step=\"3\">۳. میزکار</span></div><div id=\"msg\" role=\"status\" aria-live=\"polite\">در حال بررسی ورود تلگرام...</div><form id=\"form\" hidden><label>نوع انتخابات<select name=\"election_type\"><option value=\"council\">شوراهای اسلامی</option><option value=\"parliament\">مجلس</option><option value=\"presidency\">ریاست جمهوری</option><option value=\"other\">سایر</option></select></label><label>مرحله<select name=\"stage\"><option value=\"planning\">برنامه‌ریزی</option><option value=\"registration\">ثبت‌نام</option><option value=\"operations\">اجرا</option><option value=\"report\">گزارش</option></select></label><label>حوزه انتخابیه<input name=\"district\" maxlength=\"200\" required></label><label>معرفی کوتاه<textarea name=\"professional_summary\" maxlength=\"2000\"></textarea></label><button type=\"submit\" id=\"save\">ذخیره و ادامه</button><button type=\"button\" id=\"reload\">بارگذاری دوباره</button><small>داده‌های این محیط آزمایشی ممکن است پاک شوند. اطلاعات واقعی و حساس وارد نکنید.</small></form><section id=\"review\" class=\"panel\" hidden><h2>بررسی اطلاعات پرونده</h2><div id=\"summary\"></div><button id=\"go-dashboard\" type=\"button\">تأیید و ورود به میزکار</button><button id=\"back-profile\" type=\"button\" class=\"secondary\">ویرایش پرونده</button></section><section id=\"dashboard\" class=\"panel\" hidden><h2>میزکار آموزشی کاندیداتوری</h2><p>پرونده آزمایشی ذخیره شده است. بخش تقویم و اهداف به پایگاه داده آزمایشی متصل‌اند. تمرین سخنرانی و پرسش‌وپاسخ نیز به پایگاه داده آزمایشی متصل است؛ استودیوی محتوای اطلاع‌رسانی عمومی نیز به پایگاه داده آزمایشی متصل است؛ سایر قابلیت‌های تکمیل‌نشده نمایشی‌اند.</p><button type=\"button\" id=\"open-membership\" class=\"secondary\">اشتراک و مدیریت درخواست آزمایشی</button><div class=\"modules\"><button type=\"button\" data-module=\"پرونده من\">پرونده من</button><button type=\"button\" data-module=\"تقویم و جلسات\">تقویم و جلسات</button><button type=\"button\" data-module=\"دستیار هوشمند\">دستیار هوشمند</button><button type=\"button\" data-module=\"تمرین و آمادگی\">تمرین و آمادگی</button><button type=\"button\" data-module=\"گزارش عملکرد\">گزارش عملکرد</button><button type=\"button\" data-module=\"استودیوی محتوا\">استودیوی محتوا</button></div><section id=\"membership-panel\" class=\"panel\" hidden>\n<h3>اشتراک‌ها و درخواست آزمایشی</h3>\n<p>این محیط فقط برای آزمایش گردش‌کار است: پرداخت واقعی و آپلود رسید فعال نیست، شماره کارت نمایش داده نمی‌شود و هیچ انتقال وجهی انجام ندهید.</p>\n<div id=\"membership-state\" role=\"status\" aria-live=\"polite\"></div>\n<div id=\"membership-summary\"></div>\n<div class=\"membership-plans\">\n<article><strong>رایگان</strong><p>نسخه فعلی آزمایشی — بدون پرداخت</p></article>\n<article><strong>حرفه‌ای (طرح موردنظر)</strong><p>۳۰ روز / ۶٬۹۰۰٬۰۰۰ تومان</p><small>قیمت نمایشی است؛ امکانات ویژه و دریافت پرداخت واقعی هنوز فعال نشده‌اند.</small></article>\n</div>\n<button type=\"button\" id=\"membership-demo-request\">ثبت درخواست کاملاً آزمایشی — بدون پرداخت یا رسید</button>\n<button type=\"button\" id=\"membership-refresh\" class=\"secondary\">بررسی وضعیت درخواست</button>\n<h4>سوابق درخواست‌های آزمایشی من</h4>\n<div id=\"membership-requests\" role=\"list\"></div>\n<section id=\"membership-admin\" class=\"panel\" hidden>\n<h4>بررسی آزمایشی درخواست‌ها — فقط ادمین مجاز</h4>\n<p>تأیید این بخش، صرفاً دسترسی نمایشی ۳۰روزه در پایگاه داده آزمایشی ایجاد می‌کند؛ تأیید دریافت پول واقعی نیست.</p>\n<button type=\"button\" id=\"membership-admin-refresh\" class=\"secondary\">بازخوانی صف بررسی</button>\n<div id=\"membership-admin-queue\" role=\"list\"></div>\n</section>\n<button type=\"button\" id=\"membership-close\" class=\"secondary\">بازگشت به میزکار</button>\n</section><section id=\"progress-panel\" class=\"panel\" hidden>\n<h3>گزارش یکپارچه پیشرفت من</h3>\n<p>آمار واقعی فعالیت‌های همین حساب آزمایشی در پرونده، اهداف، تقویم، تمرین و آزمون. این اعداد ارزیابی صلاحیت یا عملکرد انتخاباتی نیستند.</p>\n<div id=\"progress-state\" role=\"status\" aria-live=\"polite\"></div>\n<div id=\"progress-cards\" class=\"progress-cards\"></div>\n<div id=\"progress-charts\" class=\"panel\"></div>\n<label>خلاصه متنی قابل انتخاب و کپی\n<textarea id=\"progress-export\" readonly rows=\"8\" aria-label=\"گزارش پیشرفت متنی\"></textarea></label>\n<div id=\"progress-print\" class=\"progress-print\" hidden aria-label=\"نسخه چاپی گزارش پیشرفت\"></div>\n<div class=\"progress-export-tools\">\n<button id=\"progress-print-button\" type=\"button\">چاپ / ذخیره به صورت PDF</button>\n<button id=\"progress-download-html\" type=\"button\" class=\"secondary\">دریافت نسخه HTML قابل چاپ</button>\n</div>\n<small>برای ساخت PDF در پنجره چاپ، گزینه «Save as PDF / ذخیره به‌صورت PDF» را انتخاب کنید. اگر چاپ داخل تلگرام در دسترس نبود، نسخه HTML را دریافت و در مرورگر باز کنید. گزارش فقط روی دستگاه شما ساخته می‌شود.</small><button id=\"progress-copy\" type=\"button\" class=\"secondary\">کپی خلاصه گزارش</button>\n<button id=\"progress-refresh\" type=\"button\" class=\"secondary\">به‌روزرسانی آمار</button>\n<button id=\"progress-close\" type=\"button\" class=\"secondary\">بازگشت به اهداف و پیگیری عملکرد</button>\n<small>مبنای محاسبه: تمام سوابق همین حساب آزمایشی. «امتیاز شخصی» توسط خود کاربر تعیین می‌شود؛ درصد آزمون نسبت پاسخ‌های صحیح به کل پاسخ‌های ثبت‌شده در همه نوبت‌هاست. داده محرمانه وارد نکنید.</small>\n</section><section id=\"goals-panel\" class=\"panel\" hidden><h3>اهداف و پیگیری عملکرد</h3><button type=\"button\" id=\"open-progress\" class=\"secondary\">مشاهده گزارش یکپارچه پیشرفت</button><form id=\"goals-form\"><label>عنوان هدف<input name=\"title\" minlength=\"3\" maxlength=\"180\" required></label><label>توضیحات<textarea name=\"details\" maxlength=\"1000\"></textarea></label><label>مهلت<input name=\"target_date\" type=\"date\"></label><button type=\"submit\">ثبت هدف</button></form><div id=\"goals-progress\" role=\"status\"></div><div id=\"goals-list\" role=\"list\"></div><button type=\"button\" id=\"goals-close\" class=\"secondary\">بازگشت به میزکار</button></section><section id=\"quiz-panel\" class=\"panel\" hidden>\n<h3>آزمون‌های آموزشی و سنجش دانش</h3>\n<p>سؤال‌های بی‌طرفانه درباره سواد رسانه‌ای و پاسخ‌گویی عمومی. نتیجه توسط سرور محاسبه می‌شود؛ پاسخ درست پس از ثبت کامل آزمون نمایش داده می‌شود.</p>\n<div id=\"quiz-status\" role=\"status\" aria-live=\"polite\"></div>\n<div id=\"quiz-catalog\" class=\"panel\"></div>\n<form id=\"quiz-form\" hidden>\n<h4 id=\"quiz-form-title\"></h4>\n<div id=\"quiz-questions\" class=\"panel\"></div>\n<button type=\"submit\" id=\"quiz-submit\">ثبت پاسخ‌ها و مشاهده نتیجه</button>\n<button type=\"button\" id=\"quiz-cancel\" class=\"secondary\">انصراف از این آزمون</button>\n</form>\n<section id=\"quiz-result\" class=\"panel\" hidden><h4>نتیجه آزمون</h4><div id=\"quiz-score\"></div><div id=\"quiz-feedback\"></div><button id=\"quiz-result-close\" type=\"button\" class=\"secondary\">بازگشت به فهرست آزمون‌ها</button></section>\n<section class=\"panel\"><h4>سوابق آزمون‌های من</h4><div id=\"quiz-history\"></div></section>\n<button id=\"quiz-close\" type=\"button\" class=\"secondary\">بازگشت به تمرین و آمادگی</button>\n</section><section id=\"practice-panel\" class=\"panel\" hidden>\n<h3>تمرین سخنرانی و پرسش‌وپاسخ</h3>\n<p>تمرین آموزشی با ارزیابی شخصی؛ فعلاً صدایی ضبط یا تحلیل نمی‌شود و هیچ امتیازی توسط هوش مصنوعی تولید نمی‌شود.</p>\n<button id=\"open-quiz\" type=\"button\" class=\"secondary\">آزمون‌های آموزشی و سنجش دانش</button><form id=\"practice-form\">\n<label>تمرین موردنظر\n<select name=\"exercise_key\" id=\"practice-exercise\">\n<option value=\"speech_clear\">سخنرانی: بیان روشن یک مسئله عمومی</option>\n<option value=\"speech_evidence\">سخنرانی: گزارش پروژه با داده و منبع</option>\n<option value=\"qa_unknown\">پرسش‌وپاسخ: وقتی اطلاعات کافی نیست</option>\n<option value=\"qa_followup\">پرسش‌وپاسخ: پیگیری درخواست شهروندان</option>\n</select></label>\n<p id=\"practice-prompt\"></p>\n<div><strong>زمان‌سنج تمرین: </strong><span id=\"practice-clock\" aria-live=\"off\">۰۰:۰۰</span></div>\n<div style=\"display:flex;flex-wrap:wrap;gap:8px\"><button type=\"button\" id=\"practice-start\">شروع زمان‌سنج</button><button type=\"button\" id=\"practice-stop\" class=\"secondary\">توقف</button></div>\n<input type=\"hidden\" name=\"duration_seconds\" value=\"0\"/>\n<label>نکات سخنرانی یا پیش‌نویس پاسخ\n<textarea name=\"response_text\" maxlength=\"3000\" placeholder=\"چند جمله درباره پاسخ یا نکات کلیدی بنویسید...\"></textarea></label>\n<label>بازنگری شخصی و نکته قابل بهبود\n<textarea name=\"reflection\" maxlength=\"1000\" placeholder=\"دفعه بعد چه چیزی را روشن‌تر بیان می‌کنید؟\"></textarea></label>\n<label>ارزیابی شخصی وضوح و پاسخگویی (نه ارزیابی هوش مصنوعی)\n<select name=\"self_score\">\n<option value=\"3\">۳ از ۵ — متوسط</option>\n<option value=\"1\">۱ از ۵ — نیاز به تمرین زیاد</option>\n<option value=\"2\">۲ از ۵ — نیاز به بهبود</option>\n<option value=\"4\">۴ از ۵ — خوب</option>\n<option value=\"5\">۵ از ۵ — بسیار خوب</option>\n</select></label>\n<button type=\"submit\" id=\"practice-save\">ثبت نتیجه تمرین</button>\n<small>حداقل ۵ نویسه در پیش‌نویس یا بازنگری وارد کنید؛ اطلاعات واقعی و محرمانه وارد نکنید.</small>\n</form>\n<p id=\"practice-feedback\" role=\"status\" aria-live=\"polite\"></p>\n<div id=\"practice-summary\"></div>\n<div id=\"practice-list\" role=\"list\"></div>\n<button type=\"button\" id=\"practice-close\" class=\"secondary\">بازگشت به میزکار</button>\n</section><section id=\"studio-panel\" class=\"panel\" hidden>\n<h3>استودیوی محتوای اطلاع‌رسانی عمومی</h3>\n<p>تهیه و مدیریت پیش‌نویس‌های factual و آموزشی. محتوای پیشنهادی صرفاً قالب اولیه است؛ ادعاها، تاریخ‌ها و منابع را پیش از انتشار بررسی کنید. انتشار خودکار وجود ندارد.</p>\n<form id=\"studio-form\">\n<label>نوع محتوا<select name=\"kind\" id=\"studio-kind\">\n<option value=\"service_update\">گزارش وضعیت خدمات عمومی</option>\n<option value=\"meeting_notice\">اطلاعیه جلسه عمومی</option>\n<option value=\"fact_correction\">اصلاح یا تکمیل اطلاعات منتشرشده</option>\n<option value=\"civic_education\">نکته آموزشی حقوق شهروندی</option>\n</select></label>\n<label>عنوان محتوا<input name=\"title\" maxlength=\"160\" minlength=\"3\" required placeholder=\"مثلاً وضعیت پیگیری پروژه خدماتی\"></label>\n<label>اطلاعات تأییدشده و نکات کلیدی<textarea id=\"studio-facts\" maxlength=\"1500\" placeholder=\"فقط موارد قابل استناد؛ از درج اطلاعات حساس خودداری کنید.\"></textarea></label>\n<label>منبع (اختیاری، لینک HTTPS)<input name=\"source_url\" type=\"url\" maxlength=\"800\" inputmode=\"url\" placeholder=\"https://...\"></label>\n<label>متن پیش‌نویس<textarea name=\"body\" id=\"studio-body\" maxlength=\"4000\" minlength=\"10\" required placeholder=\"متن پیش‌نویس را تولید یا ویرایش کنید.\"></textarea></label>\n<label>مرحله بازبینی<select name=\"status\">\n<option value=\"draft\">پیش‌نویس — نیازمند بررسی</option>\n<option value=\"reviewed\">بررسی‌شده توسط خودم</option>\n</select></label>\n<input id=\"studio-edit-id\" type=\"hidden\" value=\"\">\n<button type=\"button\" id=\"studio-compose\" class=\"secondary\">ساخت قالب اولیه از اطلاعات واردشده</button>\n<button type=\"submit\" id=\"studio-save\">ذخیره پیش‌نویس</button>\n<button type=\"button\" id=\"studio-copy\" class=\"secondary\">کپی متن ویرایش‌شده</button>\n<button type=\"button\" id=\"studio-reset\" class=\"secondary\">پیش‌نویس تازه</button>\n<small>اطلاعات این فرم روی محیط آزمایشی ذخیره می‌شود. این بخش هوش مصنوعی ندارد، به شبکه اجتماعی متصل نیست و خودکار چیزی منتشر نمی‌کند.</small>\n</form>\n<div id=\"studio-message\" role=\"status\" aria-live=\"polite\"></div>\n<h4>پیش‌نویس‌های ذخیره‌شده من</h4>\n<div id=\"studio-list\" role=\"list\"></div>\n<button type=\"button\" id=\"studio-close\" class=\"secondary\">بازگشت به میزکار</button>\n</section><section id=\"calendar-panel\" class=\"panel\" hidden><h3>تقویم شخصی و جلسات</h3><form id=\"calendar-form\"><label>عنوان رویداد<input name=\"title\" maxlength=\"180\" minlength=\"3\" required></label><label>زمان رویداد<input name=\"starts_at\" type=\"datetime-local\" required></label><label>یادداشت<textarea name=\"notes\" maxlength=\"1000\"></textarea></label><button type=\"submit\">ثبت رویداد</button></form><div id=\"calendar-list\" role=\"list\"></div><button type=\"button\" id=\"calendar-close\" class=\"secondary\">بازگشت به میزکار</button></section><button id=\"edit-from-home\" class=\"secondary\" type=\"button\">بازگشت به پرونده</button></section></main><script src=\"https://telegram.org/js/telegram-web-app.js\"></script><script>const msg=document.getElementById('msg'),form=document.getElementById('form'),tg=window.Telegram?.WebApp;const initData=tg?.initData||'';function status(s){msg.textContent=s}\nconst review=document.getElementById('review'),dashboard=document.getElementById('dashboard'),steps=document.getElementById('steps');\nfunction stage(number){form.hidden=number!==1;review.hidden=number!==2;dashboard.hidden=number!==3;steps.hidden=false;steps.querySelectorAll('span').forEach(s=>s.classList.toggle('active',s.dataset.step===String(number)));window.scrollTo(0,0)}\nfunction reviewProfile(){const p=Object.fromEntries(new FormData(form));document.getElementById('summary').textContent='نوع انتخابات: '+form.elements.election_type.selectedOptions[0].textContent+'\\nمرحله: '+form.elements.stage.selectedOptions[0].textContent+'\\nحوزه: '+p.district+'\\nمعرفی: '+(p.professional_summary||'—');stage(2)}\ndocument.getElementById('go-dashboard').addEventListener('click',()=>{stage(3);status('پرونده آزمایشی ثبت شده است؛ به میزکار خوش آمدید.')});\ndocument.getElementById('back-profile').addEventListener('click',()=>stage(1));\ndocument.getElementById('edit-from-home').addEventListener('click',()=>stage(1));\ndashboard.querySelectorAll('[data-module]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.module==='پرونده من'){stage(1);return}if(b.dataset.module==='تقویم و جلسات'){openCalendar();return}if(b.dataset.module==='گزارش عملکرد'){openGoals();return}if(b.dataset.module==='تمرین و آمادگی'){openPractice();return}if(b.dataset.module==='استودیوی محتوا'){openStudio();return}status('بخش «'+b.dataset.module+'» در نسخه آزمایشی بعدی تکمیل می‌شود؛ فعلاً نمایشی است.')}));\n\n// Practice UI is available only after valid Telegram profile load.\nconst quizPanel=document.getElementById('quiz-panel'),quizCatalog=document.getElementById('quiz-catalog'),quizForm=document.getElementById('quiz-form'),quizQuestions=document.getElementById('quiz-questions'),quizResult=document.getElementById('quiz-result'),quizHistory=document.getElementById('quiz-history'),quizStatus=document.getElementById('quiz-status');\nlet quizActive=null,quizBusy=false;\nasync function quizApi(action,payload={}){\n const r=await fetch('/api/quiz',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({initData,action,...payload})});\n let data;try{data=await r.json()}catch{throw Error('پاسخ سرور معتبر نیست')}\n if(!r.ok)throw Error(data.error||'QUIZ_ERROR');return data;\n}\nfunction quizElement(tag,textContent,className){\n const e=document.createElement(tag);if(textContent!==undefined)e.textContent=String(textContent);if(className)e.className=className;return e;\n}\nfunction quizClearResult(){\n quizResult.hidden=true;document.getElementById('quiz-feedback').replaceChildren();\n}\nasync function quizLoad(){\n quizCatalog.replaceChildren();quizHistory.replaceChildren();\n quizStatus.textContent='در حال بارگذاری آزمون‌ها و سوابق...';\n try{\n  const [catalog,history]=await Promise.all([quizApi('catalog'),quizApi('history')]);\n  if(!catalog.quizzes.length)quizCatalog.append(quizElement('p','هنوز آزمون منتشرشده‌ای وجود ندارد.'));\n  for(const item of catalog.quizzes){\n   const card=quizElement('article');card.className='quiz-card';\n   card.append(quizElement('strong',item.title),quizElement('p',item.description+' — '+item.question_count+' سؤال'));\n   const button=quizElement('button','شروع آزمون');button.type='button';button.addEventListener('click',()=>quizStart(item.id));card.append(button);quizCatalog.append(card);\n  }\n  const completed=history.attempts.length;\n  if(!completed)quizHistory.append(quizElement('p','هنوز آزمونی ثبت نکرده‌اید.'));\n  for(const item of history.attempts){\n   const card=quizElement('article');card.className='quiz-card';\n   card.append(quizElement('strong',item.title),quizElement('p','نتیجه: '+item.score+' از '+item.question_count+' — '+item.submitted_at));\n   const button=quizElement('button','مشاهده پاسخ‌های این نوبت');button.className='secondary';button.type='button';button.addEventListener('click',()=>quizReview(item.attempt_id));card.append(button);quizHistory.append(card);\n  }\n  quizStatus.textContent='آزمون‌ها و سوابق بارگذاری شدند. آخرین ۵۰ نتیجه نمایش داده می‌شود.';\n }catch(e){quizStatus.textContent='خطا در بارگذاری آزمون‌ها: '+e.message}\n}\nasync function quizStart(quizId){\n if(quizBusy)return;quizBusy=true;quizStatus.textContent='در حال دریافت سؤال‌های آزمون...';\n try{\n  const data=await quizApi('start',{quiz_id:quizId});\n  quizActive={id:data.quiz.id,questions:data.questions};\n  quizQuestions.replaceChildren();document.getElementById('quiz-form-title').textContent=data.quiz.title;\n  for(const question of data.questions){\n   const field=quizElement('fieldset');field.style.cssText='min-width:0;border:1px solid #96a3b2;border-radius:12px;padding:12px';\n   const legend=quizElement('legend',question.position+'. '+question.prompt);field.append(legend);\n   question.options.forEach((choice,index)=>{\n    const label=quizElement('label');label.className='quiz-option';\n    const input=document.createElement('input');input.type='radio';input.name='quiz-question-'+question.id;input.value=String(index);input.required=true;\n    label.append(input,quizElement('span',choice));field.append(label);\n   });\n   quizQuestions.append(field);\n  }\n  quizForm.hidden=false;quizCatalog.hidden=true;quizClearResult();\n  quizStatus.textContent='برای هر سؤال یک پاسخ انتخاب کن.';\n }catch(e){quizStatus.textContent='دریافت سؤال‌ها ناموفق: '+e.message}\n finally{quizBusy=false}\n}\nfunction quizDisplayFeedback(result){\n quizForm.hidden=true;quizCatalog.hidden=true;\n const label=quizElement('strong','امتیاز: '+result.score+' از '+result.question_count);\n const score=document.getElementById('quiz-score');score.replaceChildren(label);\n const list=document.getElementById('quiz-feedback');list.replaceChildren();\n for(const entry of result.feedback){\n  const card=quizElement('article');card.className='quiz-card';\n  card.append(quizElement('strong',entry.prompt));\n  card.append(quizElement('p',entry.is_correct?'پاسخ شما درست بود.':'پاسخ شما نیاز به بازبینی دارد.'));\n  card.append(quizElement('p','پاسخ درست: '+entry.correct_answer));\n  if(entry.rationale)card.append(quizElement('p','توضیح آموزشی: '+entry.rationale));\n  if(entry.source_url){\n   try{\n    const url=new URL(entry.source_url);\n    if(url.protocol==='https:'&&['www.unesco.org','www.oecd.org','legalinstruments.oecd.org'].includes(url.hostname)){\n     const a=quizElement('a','منبع آموزشی');a.href=url.href;a.target='_blank';a.rel='noopener noreferrer';card.append(a);\n    }\n   }catch{}\n  }\n  list.append(card);\n }\n quizResult.hidden=false;quizStatus.textContent='نتیجه از سرور دریافت شد؛ پاسخ‌های درست و منابع آموزشی قابل مشاهده‌اند.';\n}\nquizForm.addEventListener('submit',async e=>{\n e.preventDefault();if(!quizActive||quizBusy)return;\n const answers={};\n for(const question of quizActive.questions){\n  const chosen=quizForm.querySelector('input[name=\"quiz-question-'+question.id+'\"]:checked');\n  if(!chosen){quizStatus.textContent='لطفاً همه سؤال‌ها را پاسخ بده.';return}\n  answers[String(question.id)]=Number(chosen.value);\n }\n quizBusy=true;const btn=document.getElementById('quiz-submit');btn.disabled=true;quizStatus.textContent='در حال ثبت و محاسبه نتیجه در سرور...';\n try{\n  const data=await quizApi('submit',{quiz_id:quizActive.id,answers});\n  quizDisplayFeedback(data);await quizLoad();quizStatus.textContent='نتیجه ثبت شد و توضیح هر پاسخ در همین صفحه نمایش داده شده است.';\n }catch(error){quizStatus.textContent='ثبت آزمون ناموفق: '+error.message}\n finally{quizBusy=false;btn.disabled=false}\n});\ndocument.getElementById('quiz-cancel').addEventListener('click',()=>{quizForm.hidden=true;quizCatalog.hidden=false;quizActive=null;quizStatus.textContent='آزمون بدون ثبت نتیجه بسته شد.'});\ndocument.getElementById('quiz-result-close').addEventListener('click',()=>{quizClearResult();quizActive=null;quizCatalog.hidden=false;quizStatus.textContent='می‌توانی آزمون دیگری را شروع کنی.'});\nasync function quizReview(attemptId){\n if(quizBusy)return;quizBusy=true;quizStatus.textContent='در حال بازیابی پاسخ‌های ثبت‌شده...';\n try{const data=await quizApi('review',{attempt_id:attemptId});quizDisplayFeedback(data)}\n catch(e){quizStatus.textContent='بازیابی نتیجه ناموفق: '+e.message}\n finally{quizBusy=false}\n}\nasync function openQuiz(){\n practiceStop();practicePanel.hidden=true;quizPanel.hidden=false;quizForm.hidden=true;quizCatalog.hidden=false;quizClearResult();\n await quizLoad();\n}\ndocument.getElementById('quiz-close').addEventListener('click',()=>{\n quizPanel.hidden=true;quizForm.hidden=true;quizCatalog.hidden=false;quizClearResult();quizActive=null;practicePanel.hidden=false;\n status('بازگشت به تمرین و آمادگی.');\n});\ndocument.getElementById('open-quiz').addEventListener('click',openQuiz);\n\nconst practicePanel=document.getElementById('practice-panel');\nconst practiceForm=document.getElementById('practice-form');\nconst practiceList=document.getElementById('practice-list');\nconst practiceFeedback=document.getElementById('practice-feedback');\nconst practiceSummary=document.getElementById('practice-summary');\nconst practiceClock=document.getElementById('practice-clock');\nconst prompts={\n speech_clear:'در ۹۰ ثانیه مسئله روشنایی یک خیابان را با سه بخشِ شرح مسئله، اطلاعات قابل بررسی و راهکار اجرایی توضیح بده.',\n speech_evidence:'پیشرفت یک پروژه عمومی را به زبان روشن گزارش کن؛ منبع هر عدد را مشخص کن و از آمار ساختگی خودداری کن.',\n qa_unknown:'اگر درباره جزئیات بودجه اطلاعات کافی نداری، چگونه شفاف توضیح می‌دهی که چه چیزی را نمی‌دانی و چگونه بررسی می‌کنی؟',\n qa_followup:'اگر شهروندی از تأخیر رسیدگی شکایت دارد، مسیر ثبت، پیگیری و پاسخگویی را چگونه روشن بیان می‌کنی؟'\n};\ndocument.getElementById('practice-exercise').addEventListener('change',e=>{\n document.getElementById('practice-prompt').textContent=prompts[e.target.value]||'';\n});\ndocument.getElementById('practice-exercise').dispatchEvent(new Event('change'));\nlet practiceStarted=null,practiceTimer=null,practiceSeconds=0;\nfunction practiceShowTime(){const m=String(Math.floor(practiceSeconds/60)).padStart(2,'0'),s=String(practiceSeconds%60).padStart(2,'0');practiceClock.textContent=m+':'+s;practiceForm.elements.duration_seconds.value=String(practiceSeconds)}\nfunction practiceStop(){\n if(practiceStarted!==null)practiceSeconds=Math.min(900,Math.floor((Date.now()-practiceStarted)/1000));\n practiceStarted=null;if(practiceTimer!==null)clearInterval(practiceTimer);practiceTimer=null;practiceShowTime();\n}\ndocument.getElementById('practice-start').addEventListener('click',()=>{\n practiceStop();practiceSeconds=0;practiceStarted=Date.now();\n practiceTimer=setInterval(()=>{practiceSeconds=Math.min(900,Math.floor((Date.now()-practiceStarted)/1000));practiceShowTime();if(practiceSeconds===900)practiceStop()},1000);\n practiceShowTime();\n});\ndocument.getElementById('practice-stop').addEventListener('click',practiceStop);\nasync function practiceApi(action,payload={}){\n const r=await fetch('/api/practice',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({initData,action,...payload})});\n let data;try{data=await r.json()}catch{throw Error('پاسخ سرور معتبر نیست')}\n if(!r.ok)throw Error(data.error||'PRACTICE_ERROR');return data;\n}\nfunction practiceRender(items){\n practiceList.replaceChildren();\n const count=items.length,total=items.reduce((sum,x)=>sum+x.self_score,0);\n practiceSummary.textContent='تعداد تمرین‌های ثبت‌شده: '+count+' | میانگین ارزیابی شخصی: '+(count?(total/count).toFixed(1):'—')+' از ۵ (حداکثر ۱۰۰ تمرین آخر نمایش داده می‌شود)';\n if(!count){const p=document.createElement('p');p.textContent='هنوز تمرینی ثبت نکرده‌اید.';practiceList.append(p);return}\n for(const item of items){\n  const card=document.createElement('article');card.setAttribute('role','listitem');card.style.cssText='border:1px solid #96a3b2;border-radius:12px;padding:12px;margin:10px 0';\n  const title=document.createElement('strong');title.textContent=(item.kind==='speech'?'سخنرانی':'پرسش‌وپاسخ')+' — '+(document.querySelector('#practice-exercise option[value=\"'+item.exercise_key+'\"]')?.textContent||item.exercise_key);\n  const info=document.createElement('p');info.textContent='امتیاز شخصی '+item.self_score+' از ۵ | زمان '+item.duration_seconds+' ثانیه | '+item.created_at;\n  const response=document.createElement('p');response.textContent=item.response_text||'بدون متن پاسخ';\n  const reflection=document.createElement('p');reflection.textContent='بازنگری: '+(item.reflection||'—');\n  const del=document.createElement('button');del.type='button';del.textContent='حذف این تمرین';del.className='secondary';\n  del.addEventListener('click',async()=>{\n   del.disabled=true;try{await practiceApi('delete',{id:item.id});await practiceRefresh()}\n   catch(e){practiceFeedback.textContent='حذف ناموفق: '+e.message;del.disabled=false}\n  });\n  card.append(title,info,response,reflection,del);practiceList.append(card);\n }\n}\nasync function practiceRefresh(){\n practiceFeedback.textContent='در حال دریافت تمرین‌ها...';\n try{const result=await practiceApi('list');practiceRender(result.sessions);practiceFeedback.textContent='سوابق تمرین بارگذاری شد.'}\n catch(e){practiceFeedback.textContent='بازیابی ناموفق: '+e.message}\n}\nasync function openPractice(){\n practicePanel.hidden=false;dashboard.querySelector('.modules').hidden=true;\n await practiceRefresh();\n}\npracticeForm.addEventListener('submit',async e=>{\n e.preventDefault();practiceStop();\n const button=document.getElementById('practice-save');button.disabled=true;\n const values=Object.fromEntries(new FormData(practiceForm));\n const data={exercise_key:values.exercise_key,response_text:values.response_text,reflection:values.reflection,self_score:Number(values.self_score),duration_seconds:Number(values.duration_seconds)};\n try{\n  await practiceApi('create',data);\n  practiceFeedback.textContent='تمرین در پایگاه داده آزمایشی ذخیره شد.';\n  practiceForm.elements.response_text.value='';practiceForm.elements.reflection.value='';\n  practiceSeconds=0;practiceShowTime();await practiceRefresh();\n }catch(e){practiceFeedback.textContent='ثبت ناموفق: '+e.message}\n finally{button.disabled=false}\n});\ndocument.getElementById('practice-close').addEventListener('click',()=>{\n practiceStop();practicePanel.hidden=true;dashboard.querySelector('.modules').hidden=false;\n status('بازگشت به میزکار آزمایشی.');\n});\n\n// User-owned, read-only progress dashboard. Never imply the self-rating is AI generated.\n// Create a private print-ready snapshot from the already authenticated report response.\n// No signed initData, Telegram user ID, private profile fields or network requests are included.\nconst reportPrintRoot=document.getElementById('progress-print');\nconst reportPrintCss=\"@media print {\\n@page{size:A4;margin:14mm}\\nhtml,body{background:#fff!important;color:#182c35!important}\\nbody *{visibility:hidden!important}\\n#progress-print,#progress-print *{visibility:visible!important}\\n#progress-print{display:block!important;position:absolute!important;inset:0 auto auto 0!important;width:100%!important;max-width:none!important;min-height:auto!important;margin:0!important;padding:0!important;background:#fff!important;color:#182c35!important;box-shadow:none!important;direction:rtl!important;font-family:Tahoma,Arial,sans-serif!important}\\n#progress-print .print-page{border:0!important}\\n#progress-print .print-grid{display:grid!important;grid-template-columns:1fr 1fr!important;gap:10px!important}\\n#progress-print .print-card,#progress-print .print-section{break-inside:avoid;page-break-inside:avoid;border:1px solid #d2dce2!important;border-radius:9px!important;padding:12px!important;margin:0 0 10px!important}\\n#progress-print .print-footer{border-top:1px solid #d2dce2!important;padding-top:8px!important;font-size:10px!important}\\n#progress-print h1{font-size:21px!important;margin:0 0 10px!important}\\n#progress-print h2{font-size:14px!important;margin:0 0 8px!important}\\n#progress-print p,#progress-print span,#progress-print strong{font-size:11px!important;line-height:1.9!important}\\n#progress-print .print-value{font-size:22px!important;font-weight:bold!important;display:block!important}\\n#progress-print progress{accent-color:#24554c!important;width:100%!important}\\n}\\n.progress-export-tools{display:grid;gap:8px}\\n.print-page{direction:rtl;line-height:1.8;color:#182c35;background:#fff}\\n.print-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:14px 0}\\n.print-card,.print-section{border:1px solid #d2dce2;border-radius:10px;padding:13px;overflow-wrap:anywhere}\\n.print-card h2,.print-section h2{margin:0 0 8px;font-size:14px}\\n.print-card .print-value{font-size:22px;font-weight:bold;display:block}\\n.print-header{border-bottom:2px solid #24554c;padding:0 0 14px}\\n.print-header h1{margin:0 0 6px}\\n.print-footer{font-size:11px;color:#556a72;margin-top:18px;border-top:1px solid #d2dce2;padding-top:12px}\\n@media(max-width:340px){.print-grid{grid-template-columns:1fr}}\\n\";\nfunction reportPrintElement(tag,content,className){\n  const element=document.createElement(tag);\n  if(content!==undefined)element.textContent=String(content);\n  if(className)element.className=className;\n  return element;\n}\nfunction reportPrintCard(parent,name,value,detail){\n  const card=reportPrintElement('section',undefined,'print-card');\n  card.append(reportPrintElement('h2',name),reportPrintElement('span',value,'print-value'),reportPrintElement('p',detail));\n  parent.append(card);\n}\nfunction reportBuildPrint(data){\n  reportPrintRoot.replaceChildren();\n  const container=reportPrintElement('article',undefined,'print-page');\n  const header=reportPrintElement('header',undefined,'print-header');\n  header.append(reportPrintElement('h1','گزارش پیشرفت آموزشی کاندیداتوری'));\n  header.append(reportPrintElement('p','گزارش شخصی فعالیت‌های ثبت‌شده در نسخه آزمایشی؛ بدون اطلاعات هویتی و بدون شماره حساب تلگرام.'));\n  let dt;try{dt=new Intl.DateTimeFormat('fa-IR',{dateStyle:'long',timeStyle:'short'}).format(new Date(data.generated_at))}catch{dt='تاریخ نامشخص'}\n  header.append(reportPrintElement('p','تاریخ تهیه گزارش: '+dt));\n  container.append(header);\n  const grid=reportPrintElement('section',undefined,'print-grid'),g=data.goals,c=data.calendar,p=data.practice,q=data.quizzes;\n  reportPrintCard(grid,'پرونده',data.profile.completed?'تکمیل‌شده':'تکمیل‌نشده','وضعیت ثبت اطلاعات پایه');\n  reportPrintCard(grid,'اهداف',g.completed+' از '+g.total,g.overdue+' هدف باز دارای مهلت گذشته');\n  reportPrintCard(grid,'رویدادها',c.completed+' از '+c.total,c.scheduled+' رویداد برنامه‌ریزی‌شده');\n  reportPrintCard(grid,'تمرین‌ها',p.total+' مورد',p.speech+' سخنرانی و '+p.qa+' پرسش‌وپاسخ');\n  reportPrintCard(grid,'زمان تمرین',Math.round(p.duration_seconds/60)+' دقیقه','مدت جمع‌شده از زمان‌سنج‌های ثبت‌شده، با گرد کردن به دقیقه');\n  reportPrintCard(grid,'ارزیابی شخصی',p.self_rating===null?'بدون داده':p.self_rating+' از ۵','امتیاز خوداظهاری؛ نه سنجش صوتی یا هوش مصنوعی');\n  reportPrintCard(grid,'نوبت‌های آزمون',q.attempts+' نوبت',q.unique_quizzes+' آزمون متفاوت از '+q.available_quizzes+' آزمون منتشرشده');\n  reportPrintCard(grid,'دقت پاسخ‌ها',q.correct_percentage===null?'بدون داده':q.correct_percentage+'٪',q.correct_answers+' پاسخ صحیح از '+q.answered_questions+' پاسخ ثبت‌شده در تمام نوبت‌ها');\n  container.append(grid);\n  const method=reportPrintElement('section',undefined,'print-section');\n  method.append(reportPrintElement('h2','روش محاسبه و محدودیت‌ها'));\n  method.append(reportPrintElement('p','آمار اهداف و جلسات با شمارش رکوردهای ذخیره‌شده محاسبه می‌شود. مقدار پیشرفت نشان‌دهنده وضعیت ثبت‌شده توسط خود کاربر است.'));\n  method.append(reportPrintElement('p','درصد پاسخ‌های صحیح، نسبت مجموع پاسخ‌های صحیح به کل پاسخ‌های ثبت‌شده در تمام نوبت‌های آزمون است؛ این گزارش برآورد صلاحیت حرفه‌ای یا انتخاباتی نیست.'));\n  method.append(reportPrintElement('p','میانگین ارزیابی تمرین‌ها خوداظهاری است و هیچ تحلیل خودکار صدا، شخصیت یا عملکرد انتخاباتی انجام نشده است.'));\n  container.append(method);\n  const footer=reportPrintElement('footer','CANDIDATORY — گزارش آموزشی آزمایشی | داده‌ها فقط در همین دستگاه قالب‌بندی شده‌اند و این خروجی به سرور جدیدی ارسال نمی‌شود.','print-footer');\n  container.append(footer);\n  reportPrintRoot.append(container);\n}\nfunction reportPrintDoc(){\n  const cloned=reportPrintRoot.cloneNode(true);cloned.hidden=false;\n  return '<!doctype html><html lang=\"fa\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex\"><title>گزارش پیشرفت کاندیداتوری</title><style>'+reportPrintCss+'body{font-family:Tahoma,Arial,sans-serif;direction:rtl;background:#f4f6f8;color:#182c35;margin:0;padding:24px}.progress-print{max-width:820px;margin:auto;padding:20px;background:#fff;border:1px solid #d2dce2;border-radius:12px}@media print{body{margin:0;padding:0}.progress-print{border:none;max-width:none;padding:0}}</style></head><body>'+cloned.outerHTML+'</body></html>';\n}\nasync function reportRequireData(){\n  if(!progressLast)await progressRefresh();\n  if(!progressLast){progressState.textContent='گزارش هنوز دریافت نشده؛ ابتدا اتصال به سرور را بررسی کنید.';return false}\n  reportBuildPrint(progressLast);\n  return true;\n}\nfunction reportAfterPrint(){reportPrintRoot.hidden=true}\nwindow.addEventListener('afterprint',reportAfterPrint);\ndocument.getElementById('progress-print-button').addEventListener('click',async()=>{\n  if(!await reportRequireData())return;\n  reportPrintRoot.hidden=false;\n  progressState.textContent='در پنجره چاپ، «Save as PDF / ذخیره به‌صورت PDF» را انتخاب کنید. در صورت نبود این گزینه در تلگرام، نسخه HTML قابل چاپ را دریافت کنید.';\n  if(typeof window.print!=='function'){progressState.textContent='چاپ در این مرورگر پشتیبانی نمی‌شود؛ نسخه HTML قابل چاپ را دریافت کنید.';return}\n  try{window.print()}catch{progressState.textContent='چاپ در این محیط اجرا نشد؛ نسخه HTML قابل چاپ را دریافت کنید.'}\n});\ndocument.getElementById('progress-download-html').addEventListener('click',async()=>{\n  if(!await reportRequireData())return;\n  const html=reportPrintDoc();\n  const blob=new Blob([html],{type:'text/html;charset=utf-8'});\n  const url=URL.createObjectURL(blob);\n  const a=document.createElement('a');a.href=url;a.download='candidatory-progress-report.html';a.style.display='none';document.body.append(a);\n  try{a.click();progressState.textContent='نسخه HTML قابل چاپ روی دستگاه آماده دریافت شد. آن را در مرورگر باز کرده و Print → Save as PDF را انتخاب کنید.'}\n  finally{a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}\n});\n\n// Factual editorial templates only, not AI and never auto-publish.\nconst membershipPanel=document.getElementById('membership-panel');\nconst membershipState=document.getElementById('membership-state');\nconst membershipSummary=document.getElementById('membership-summary');\nconst membershipRequests=document.getElementById('membership-requests');\nconst membershipAdmin=document.getElementById('membership-admin');\nconst membershipQueue=document.getElementById('membership-admin-queue');\nasync function membershipApi(action,payload={}){\n const response=await fetch('/api/membership',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({initData,action,...payload})});\n let data;try{data=await response.json()}catch{throw Error('پاسخ سرور قابل خواندن نبود')}\n if(!response.ok)throw Error(data.error||'MEMBERSHIP_ERROR');\n return data;\n}\nfunction membershipText(tag,value){const e=document.createElement(tag);e.textContent=String(value);return e}\nfunction membershipList(items,target){\n target.replaceChildren();\n if(!items.length){target.append(membershipText('p','درخواستی برای نمایش وجود ندارد.'));return}\n for(const item of items){\n  const card=membershipText('article','');card.className='membership-card';\n  card.append(membershipText('strong','درخواست '+item.reference));\n  card.append(membershipText('p','وضعیت: '+(item.status==='pending'?'در انتظار بررسی آزمایشی':item.status==='approved'?'تأیید نمایشی':item.status==='rejected'?'رد شده':item.status)));\n  card.append(membershipText('small','زمان ثبت: '+item.created_at));\n  target.append(card);\n }\n}\nasync function membershipRefresh(){\n membershipState.textContent='در حال دریافت وضعیت اشتراک آزمایشی...';\n try{\n  const data=await membershipApi('status');\n  const plan=data.plan==='professional'?'حرفه‌ای آزمایشی':'رایگان';\n  membershipSummary.replaceChildren();\n  membershipSummary.append(membershipText('strong','وضعیت فعلی: '+plan));\n  if(data.subscription?.expires_at)membershipSummary.append(membershipText('p','پایان اعتبار ثبت‌شده: '+data.subscription.expires_at));\n  membershipSummary.append(membershipText('small','فعال‌سازی حرفه‌ای واقعی، پرداخت و تصویر رسید هنوز پشتیبانی نمی‌شوند.'));\n  membershipList(data.requests,membershipRequests);\n  membershipAdmin.hidden=!data.is_admin;\n  document.getElementById('membership-demo-request').disabled=data.requests.some(x=>x.status==='pending');\n  if(data.is_admin)await membershipAdminRefresh();\n  membershipState.textContent='وضعیت از پایگاه داده آزمایشی دریافت شد.';\n }catch(e){membershipState.textContent='خطا در دریافت وضعیت: '+e.message}\n}\nasync function membershipAdminRefresh(){\n try{\n  const response=await membershipApi('admin_queue');\n  membershipQueue.replaceChildren();\n  if(!response.requests.length){membershipQueue.append(membershipText('p','درخواست آزمایشی در انتظار بررسی وجود ندارد.'));return}\n  for(const item of response.requests){\n   const card=membershipText('article','');card.className='membership-card';\n   card.append(membershipText('strong','درخواست '+item.reference));\n   card.append(membershipText('p','شناسه حساب آزمایشی: '+item.telegram_id));\n   card.append(membershipText('small','ثبت: '+item.created_at));\n   for(const [decision,label] of [['approved','تأیید نمایشی ۳۰روزه'],['rejected','رد درخواست']]){\n    const button=membershipText('button',label);button.type='button';button.className='secondary';\n    button.addEventListener('click',async()=>{\n     button.disabled=true;\n     try{\n      await membershipApi('admin_decide',{id:item.id,decision});\n      membershipState.textContent=decision==='approved'?'دسترسی نمایشی به ثبت رسید؛ پرداختی دریافت نشده است.':'درخواست نمایشی رد شد.';\n      await membershipAdminRefresh();\n     }catch(e){membershipState.textContent='تغییر وضعیت ناموفق: '+e.message;button.disabled=false}\n    });\n    card.append(button);\n   }\n   membershipQueue.append(card);\n  }\n }catch(e){membershipState.textContent='صف ادمین در دسترس نیست: '+e.message}\n}\nasync function openMembership(){\n membershipPanel.hidden=false;\n dashboard.querySelector('.modules').hidden=true;\n await membershipRefresh();\n}\ndocument.getElementById('open-membership').addEventListener('click',openMembership);\ndocument.getElementById('membership-refresh').addEventListener('click',membershipRefresh);\ndocument.getElementById('membership-admin-refresh').addEventListener('click',membershipAdminRefresh);\ndocument.getElementById('membership-demo-request').addEventListener('click',async()=>{\n const button=document.getElementById('membership-demo-request');button.disabled=true;\n membershipState.textContent='در حال ایجاد درخواست آزمایشی بدون پرداخت...';\n try{\n  const result=await membershipApi('demo_request');\n  membershipState.textContent='درخواست نمایشی '+result.reference+' ثبت شد. هنوز هیچ پرداخت یا رسیدی وجود ندارد.';\n  await membershipRefresh();\n }catch(e){membershipState.textContent='ثبت درخواست ناموفق: '+e.message;button.disabled=false}\n});\ndocument.getElementById('membership-close').addEventListener('click',()=>{\n membershipPanel.hidden=true;dashboard.querySelector('.modules').hidden=false;\n status('بازگشت به میزکار آزمایشی.');\n});\n\nconst studioPanel=document.getElementById('studio-panel');\nconst studioForm=document.getElementById('studio-form');\nconst studioList=document.getElementById('studio-list');\nconst studioMessage=document.getElementById('studio-message');\nconst studioTypes={\n service_update:'گزارش وضعیت خدمات عمومی',\n meeting_notice:'اطلاعیه جلسه عمومی',\n fact_correction:'اصلاح یا تکمیل اطلاعات',\n civic_education:'نکته آموزشی شهروندی'\n};\nasync function studioApi(action,payload={}){\n const r=await fetch('/api/studio',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({initData,action,...payload})});\n let data;try{data=await r.json()}catch{throw Error('پاسخ سرور معتبر نبود')}\n if(!r.ok)throw Error(data.error||'STUDIO_ERROR');return data;\n}\nfunction studioTemplate(){\n const kind=studioForm.elements.kind.value;\n const title=studioForm.elements.title.value.trim();\n const facts=document.getElementById('studio-facts').value.trim();\n const source=studioForm.elements.source_url.value.trim();\n if(title.length<3){studioMessage.textContent='ابتدا عنوان مشخصی وارد کن.';return}\n const label=studioTypes[kind]||'اطلاع‌رسانی عمومی';\n const shared='\\n\\nاطلاعات قابل استناد:\\n'+(facts||'［اطلاعات تأییدشده و قابل استناد را تکمیل کنید］');\n const ending='\\n\\nمنبع: '+(source||'［منبع اطلاعات را پیش از انتشار بررسی و درج کنید］');\n const tails={\n  service_update:'\\n\\nوضعیت فعلی: ［وضعیت واقعی را وارد کنید］\\nاقدام بعدی: ［گام بعدی و مسئول پیگیری را در صورت تأیید وارد کنید］',\n  meeting_notice:'\\n\\nزمان و محل: ［تاریخ، ساعت و محل قطعی را وارد کنید］\\nموضوع و شیوه حضور: ［جزئیات تأییدشده را وارد کنید］',\n  fact_correction:'\\n\\nاطلاعات قبلی: ［ادعای دقیق قبلی را مشخص کنید］\\nاصلاحیه و شواهد: ［اصلاحیه مستند را وارد کنید］',\n  civic_education:'\\n\\nتوضیح آموزشی: ［مفهوم را از منبع معتبر و رسمی توضیح دهید］\\nدامنه و محدودیت: ［شرایط و استثناها را با منبع ذکر کنید］'\n };\n studioForm.elements.body.value=label+'\\n'+title+shared+tails[kind]+ending;\n studioForm.elements.status.value='draft';\n studioMessage.textContent='قالب اولیه ساخته شد. موارد داخل کروشه را با اطلاعات واقعی و مستند جایگزین و متن را ویرایش کن.';\n}\nfunction studioNew(){\n studioForm.reset();document.getElementById('studio-edit-id').value='';\n document.getElementById('studio-facts').value='';\n document.getElementById('studio-save').textContent='ذخیره پیش‌نویس';\n studioMessage.textContent='فرم برای پیش‌نویس تازه آماده شد.';\n}\nfunction studioRender(items){\n studioList.replaceChildren();\n if(!items.length){const p=document.createElement('p');p.textContent='هنوز پیش‌نویسی ذخیره نشده است.';studioList.append(p);return}\n for(const item of items){\n  const card=document.createElement('article');card.setAttribute('role','listitem');card.className='studio-card';\n  const heading=document.createElement('strong');heading.textContent=item.title;\n  const note=document.createElement('p');note.textContent=(studioTypes[item.kind]||'محتوا')+' | '+(item.status==='reviewed'?'بررسی‌شده توسط کاربر':'پیش‌نویس')+' | '+item.updated_at;\n  const preview=document.createElement('p');preview.textContent=item.body.length>230?item.body.slice(0,230)+'…':item.body;\n  const edit=document.createElement('button');edit.type='button';edit.textContent='ویرایش';edit.className='secondary';\n  edit.addEventListener('click',()=>{\n   studioForm.elements.kind.value=item.kind;\n   studioForm.elements.title.value=item.title;\n   studioForm.elements.source_url.value=item.source_url;\n   studioForm.elements.body.value=item.body;\n   studioForm.elements.status.value=item.status;\n   document.getElementById('studio-facts').value='';\n   document.getElementById('studio-edit-id').value=item.id;\n   document.getElementById('studio-save').textContent='ذخیره تغییرات';\n   studioMessage.textContent='پیش‌نویس برای ویرایش بارگذاری شد؛ ذخیره را بزن.';\n   studioForm.scrollIntoView({behavior:'auto',block:'start'});\n  });\n  const del=document.createElement('button');del.type='button';del.textContent='حذف';del.className='secondary';\n  del.addEventListener('click',async()=>{\n   if(!confirm('این پیش‌نویس آزمایشی حذف شود؟'))return;\n   del.disabled=true;\n   try{await studioApi('delete',{id:item.id});if(document.getElementById('studio-edit-id').value===item.id)studioNew();await studioLoad();studioMessage.textContent='پیش‌نویس حذف شد.'}\n   catch(e){studioMessage.textContent='حذف ناموفق: '+e.message}\n   finally{del.disabled=false}\n  });\n  card.append(heading,note,preview,edit,del);studioList.append(card);\n }\n}\nasync function studioLoad(){\n studioMessage.textContent='در حال دریافت پیش‌نویس‌ها...';\n try{const result=await studioApi('list');studioRender(result.drafts);studioMessage.textContent='پیش‌نویس‌های آزمایشی بارگذاری شدند.'}\n catch(e){studioMessage.textContent='دریافت پیش‌نویس‌ها ناموفق: '+e.message}\n}\nasync function openStudio(){\n studioPanel.hidden=false;dashboard.querySelector('.modules').hidden=true;\n await studioLoad();\n}\ndocument.getElementById('studio-compose').addEventListener('click',studioTemplate);\ndocument.getElementById('studio-reset').addEventListener('click',studioNew);\nstudioForm.addEventListener('submit',async e=>{\n e.preventDefault();\n const button=document.getElementById('studio-save');button.disabled=true;\n const data=Object.fromEntries(new FormData(studioForm));data.source_url=data.source_url.trim();\n const id=document.getElementById('studio-edit-id').value;\n try{\n  await studioApi(id?'update':'create',{...data,...(id?{id}:{})});\n  studioNew();await studioLoad();studioMessage.textContent='متن در پایگاه داده آزمایشی ذخیره شد؛ هیچ انتشار خودکاری انجام نشد.';\n }catch(error){studioMessage.textContent='ذخیره ناموفق: '+error.message}\n finally{button.disabled=false}\n});\ndocument.getElementById('studio-copy').addEventListener('click',async()=>{\n const body=studioForm.elements.body.value;\n if(!body.trim()){studioMessage.textContent='متنی برای کپی وارد نشده است.';return}\n try{await navigator.clipboard.writeText(body);studioMessage.textContent='متن پیش‌نویس کپی شد.'}\n catch{studioForm.elements.body.focus();studioForm.elements.body.select();studioMessage.textContent='متن انتخاب شد؛ از گزینه Copy دستگاه استفاده کن.'}\n});\ndocument.getElementById('studio-close').addEventListener('click',()=>{\n studioPanel.hidden=true;dashboard.querySelector('.modules').hidden=false;status('بازگشت به میزکار آزمایشی.');\n});\n\nconst progressPanel=document.getElementById('progress-panel');\nconst progressCards=document.getElementById('progress-cards');\nconst progressCharts=document.getElementById('progress-charts');\nconst progressState=document.getElementById('progress-state');\nconst progressExport=document.getElementById('progress-export');\nconst progressFormat=(n,unit='')=>new Intl.NumberFormat('fa-IR',{maximumFractionDigits:1}).format(n)+(unit?' '+unit:'');\nlet progressLast=null;\nasync function progressApi(){\n  const response=await fetch('/api/progress',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({initData,action:'overview'})});\n  const data=await response.json();\n  if(!response.ok)throw Error(data.error||'PROGRESS_ERROR');\n  return data;\n}\nfunction progressCard(title,value,note){\n  const article=document.createElement('article');article.className='progress-card';\n  const name=document.createElement('strong');name.textContent=title;\n  const number=document.createElement('div');number.className='progress-number';number.textContent=value;\n  const desc=document.createElement('small');desc.textContent=note;\n  article.append(name,number,desc);progressCards.append(article);\n}\nfunction progressBar(title,current,total,note){\n  const wrap=document.createElement('section');wrap.className='progress-bar-card';\n  const label=document.createElement('strong');label.textContent=title+' — '+progressFormat(current)+' از '+progressFormat(total);\n  const bar=document.createElement('progress');bar.max=Math.max(total,1);bar.value=current;bar.setAttribute('aria-label',title);\n  const desc=document.createElement('small');desc.textContent=note;\n  wrap.append(label,bar,desc);progressCharts.append(wrap);\n}\nfunction progressRender(data){\n  progressLast=data;progressCards.replaceChildren();progressCharts.replaceChildren();\n  const g=data.goals,c=data.calendar,p=data.practice,q=data.quizzes;\n  progressCard('پرونده',data.profile.completed?'تکمیل‌شده':'تکمیل‌نشده','ثبت اطلاعات اولیه');\n  progressCard('اهداف',progressFormat(g.completed)+' / '+progressFormat(g.total),progressFormat(g.overdue)+' هدف باز با مهلت گذشته');\n  progressCard('تقویم و جلسات',progressFormat(c.completed)+' / '+progressFormat(c.total),progressFormat(c.scheduled)+' رویداد برنامه‌ریزی‌شده');\n  progressCard('تمرین‌های ثبت‌شده',progressFormat(p.total),progressFormat(p.speech)+' سخنرانی و '+progressFormat(p.qa)+' پرسش‌وپاسخ');\n  progressCard('زمان تمرین',progressFormat(Math.round(p.duration_seconds/60))+' دقیقه','جمع مدت زمان‌سنج‌های ثبت‌شده؛ مقدار تقریبی');\n  progressCard('میانگین ارزیابی شخصی',p.self_rating===null?'بدون داده':progressFormat(p.self_rating)+' / ۵','خودارزیابی کاربر، نه تحلیل هوش مصنوعی');\n  progressCard('دفعات آزمون',progressFormat(q.attempts),progressFormat(q.unique_quizzes)+' آزمون متفاوت از '+progressFormat(q.available_quizzes)+' آزمون منتشرشده');\n  progressCard('پاسخ‌های صحیح',q.correct_percentage===null?'بدون داده':progressFormat(q.correct_percentage)+'٪',progressFormat(q.correct_answers)+' از '+progressFormat(q.answered_questions)+' پاسخ، در تمام نوبت‌ها');\n  progressBar('پیشرفت اهداف',g.completed,g.total,g.total?'نسبت اهدافی که انجام‌شده علامت خورده‌اند':'هنوز هدفی ثبت نشده است');\n  progressBar('تکمیل رویدادهای تقویم',c.completed,c.total,c.total?'نسبت رویدادهای انجام‌شده به همه رویدادهای ثبت‌شده':'هنوز رویدادی ثبت نشده است');\n  progressBar('آزمون‌های متفاوت تکمیل‌شده',q.unique_quizzes,q.available_quizzes,q.available_quizzes?'تعداد آزمون‌های متفاوتی که حداقل یک‌بار ثبت شده‌اند':'آزمون منتشرشده‌ای وجود ندارد');\n  progressExport.value=[\n    'گزارش پیشرفت حساب آزمایشی کاندیداتوری',\n    'زمان تولید (UTC): '+data.generated_at,\n    'پرونده: '+(data.profile.completed?'تکمیل‌شده':'تکمیل‌نشده'),\n    'اهداف: '+g.completed+' از '+g.total+' انجام‌شده؛ '+g.overdue+' دارای مهلت گذشته',\n    'تقویم: '+c.completed+' از '+c.total+' انجام‌شده؛ '+c.scheduled+' برنامه‌ریزی‌شده',\n    'تمرین: '+p.total+' مورد (سخنرانی '+p.speech+'، پرسش‌وپاسخ '+p.qa+')',\n    'زمان ثبت‌شده تمرین: '+p.duration_seconds+' ثانیه',\n    'میانگین خودارزیابی: '+(p.self_rating===null?'بدون داده':p.self_rating+' از ۵'),\n    'آزمون: '+q.attempts+' نوبت، '+q.unique_quizzes+' آزمون متفاوت از '+q.available_quizzes+' آزمون منتشرشده',\n    'درصد پاسخ صحیح در همه نوبت‌ها: '+(q.correct_percentage===null?'بدون داده':q.correct_percentage+'٪'),\n    'این آمار نشانگر فعالیت ثبت‌شده است و صلاحیت یا عملکرد انتخاباتی را ارزیابی نمی‌کند.'\n  ].join('\\n');\n}\nasync function progressRefresh(){\n  progressState.textContent='در حال دریافت اطلاعات واقعی پیشرفت...';\n  const btn=document.getElementById('progress-refresh');btn.disabled=true;\n  try{const data=await progressApi();progressRender(data);progressState.textContent='گزارش از پایگاه داده آزمایشی به‌روز شد.'}\n  catch(e){progressState.textContent='بارگذاری گزارش ناموفق: '+e.message}\n  finally{btn.disabled=false}\n}\nasync function openProgress(){\n  goalsPanel.hidden=true;progressPanel.hidden=false;await progressRefresh();\n}\ndocument.getElementById('progress-refresh').addEventListener('click',progressRefresh);\ndocument.getElementById('progress-close').addEventListener('click',()=>{progressPanel.hidden=true;goalsPanel.hidden=false;status('بازگشت به اهداف و پیگیری عملکرد.')});\ndocument.getElementById('open-progress').addEventListener('click',openProgress);\ndocument.getElementById('progress-copy').addEventListener('click',async()=>{\n  if(!progressLast){progressState.textContent='ابتدا گزارش را بارگذاری کنید.';return}\n  try{await navigator.clipboard.writeText(progressExport.value);progressState.textContent='خلاصه گزارش کپی شد.'}\n  catch{progressExport.focus();progressExport.select();progressState.textContent='خلاصه انتخاب شد؛ از گزینه Copy دستگاه استفاده کنید.'}\n});\n\nconst goalsPanel=document.getElementById('goals-panel'),goalsForm=document.getElementById('goals-form'),goalsList=document.getElementById('goals-list');\nasync function goalsApi(action,payload={}){const response=await fetch('/api/goals',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({initData,action,...payload})});const data=await response.json();if(!response.ok)throw Error(data.error||'GOALS_ERROR');return data}\nfunction goalsRender(rows){goalsList.replaceChildren();document.getElementById('goals-progress').textContent='اهداف انجام‌شده: '+rows.filter(x=>x.status==='done').length+' از '+rows.length;\nif(!rows.length){const empty=document.createElement('p');empty.textContent='هنوز هدفی ثبت نشده است.';goalsList.append(empty)}\nfor(const x of rows){const card=document.createElement('article');card.setAttribute('role','listitem');card.style.cssText='padding:12px;margin:10px 0;border:1px solid #96a3b2;border-radius:12px';\nconst name=document.createElement('strong');name.textContent=x.title;const detail=document.createElement('p');detail.textContent=(x.details||'')+' — '+(x.target_date||'بدون مهلت');const toggle=document.createElement('button');toggle.type='button';toggle.textContent=x.status==='done'?'بازگشت به باز':'انجام شد';toggle.addEventListener('click',()=>goalsChange('status',{id:x.id,status:x.status==='done'?'open':'done'}));const remove=document.createElement('button');remove.type='button';remove.textContent='حذف';remove.addEventListener('click',()=>goalsChange('delete',{id:x.id}));card.append(name,detail,toggle,remove);goalsList.append(card)}}\nasync function goalsRefresh(){try{const data=await goalsApi('list');goalsRender(data.goals);status('اهداف بارگذاری شد.')}catch(e){status('خطای اهداف: '+e.message)}}\nasync function goalsChange(action,payload){try{await goalsApi(action,payload);await goalsRefresh();return true}catch(e){status('خطای اهداف: '+e.message);return false}}\nasync function openGoals(){goalsPanel.hidden=false;dashboard.querySelector('.modules').hidden=true;await goalsRefresh()}\ngoalsForm.addEventListener('submit',async event=>{event.preventDefault();const b=goalsForm.querySelector('button');b.disabled=true;try{if(await goalsChange('create',Object.fromEntries(new FormData(goalsForm))))goalsForm.reset()}finally{b.disabled=false}});\ndocument.getElementById('goals-close').addEventListener('click',()=>{goalsPanel.hidden=true;dashboard.querySelector('.modules').hidden=false;status('بازگشت به میزکار.')});\n\nconst calendarPanel=document.getElementById('calendar-panel'), calendarList=document.getElementById('calendar-list'),calendarForm=document.getElementById('calendar-form');\nasync function calendarApi(action,payload={}){const r=await fetch('/api/calendar',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({initData,action,...payload})});const d=await r.json();if(!r.ok)throw Error(d.error||'CALENDAR_ERROR');return d}\nfunction calendarRender(rows){calendarList.replaceChildren();if(!rows.length){const empty=document.createElement('p');empty.textContent='هنوز رویدادی ثبت نشده است.';calendarList.append(empty);return}\nfor(const item of rows){const card=document.createElement('article');card.setAttribute('role','listitem');card.style.cssText='padding:12px;margin:10px 0;border:1px solid #96a3b2;border-radius:12px';const title=document.createElement('strong');title.textContent=item.title;const detail=document.createElement('p');detail.textContent=item.starts_at+' — '+item.status+(item.notes?' — '+item.notes:'');const done=document.createElement('button');done.type='button';done.textContent=item.status==='done'?'بازگشت به برنامه':'انجام شد';done.className='secondary';done.addEventListener('click',()=>calendarChange('status',{id:item.id,status:item.status==='done'?'scheduled':'done'}));const del=document.createElement('button');del.type='button';del.className='secondary';del.textContent='حذف';del.addEventListener('click',()=>calendarChange('delete',{id:item.id}));card.append(title,detail,done,del);calendarList.append(card)}}\nasync function openCalendar(){calendarPanel.hidden=false;document.querySelector('.modules').hidden=true;await calendarRefresh()}\nasync function calendarRefresh(){status('در حال دریافت رویدادها...');try{const data=await calendarApi('list');calendarRender(data.events);status('رویدادهای حساب آزمایشی شما بارگذاری شد.')}catch(e){status('خطای تقویم: '+e.message)}}\nasync function calendarChange(action,payload){try{await calendarApi(action,payload);await calendarRefresh()}catch(e){status('خطای تقویم: '+e.message)}}\ncalendarForm.addEventListener('submit',async e=>{e.preventDefault();const submit=calendarForm.querySelector('[type=submit]');submit.disabled=true;const v=Object.fromEntries(new FormData(calendarForm));try{await calendarChange('create',v);calendarForm.reset()}finally{submit.disabled=false}});\ndocument.getElementById('calendar-close').addEventListener('click',()=>{calendarPanel.hidden=true;document.querySelector('.modules').hidden=false;status('بازگشت به میزکار آزمایشی.')});\nasync function request(action,profile){const r=await fetch('/api/profile',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({initData,action,profile,details:{}})});const data=await r.json();if(!r.ok)throw Error(data.reason?data.error+' ('+data.reason+')':data.error||'API_ERROR');return data}async function load(){form.hidden=true;status('در حال اعتبارسنجی ورود تلگرام...');try{const data=await request('get');if(data.profile)for(const [k,v]of Object.entries(data.profile))if(form.elements.namedItem(k))form.elements.namedItem(k).value=v;stage(1);status('اتصال معتبر است. پرونده را تکمیل کنید و ذخیره و ادامه را بزنید.')}catch(e){let hint='';try{const d=await fetch('/api/bot-info').then(r=>r.json());hint=d.botUsername?' ربات متصل به سرور: @'+d.botUsername:d.telegramTokenValid===false?' توکن ربات سرور نامعتبر یا باطل‌شده است.':'';}catch{}status('احراز هویت ناموفق: '+e.message+'.'+hint+' دکمه مینی‌اپ باید متعلق به همان رباتی باشد که توکنش در Cloudflare ثبت شده است.')}}if(!initData){status('برای ورود معتبر، این صفحه باید از داخل مینی‌اپ ربات آزمایشی تلگرام باز شود.');}else{tg?.ready();load()}form.addEventListener('submit',async e=>{e.preventDefault();const b=document.getElementById('save');b.disabled=true;status('در حال ذخیره...');try{const profile=Object.fromEntries(new FormData(form));await request('save',profile);status('ذخیره موفق بود. اطلاعات را مرور کنید.');reviewProfile()}catch(err){status('ذخیره ناموفق: '+err.message)}finally{b.disabled=false}});document.getElementById('reload').addEventListener('click',load);</script></body></html>";
// Isolated authenticated integration API. Never deploy to production or public preview.
// Authenticated, owner-scoped practice sessions. No AI or speech-scoring claims.
const PRACTICE_EXERCISES = Object.freeze({
  speech_clear: {kind:"speech", title:"بیان روشن یک مسئله عمومی"},
  speech_evidence: {kind:"speech", title:"گزارش یک پروژه با داده و منبع"},
  qa_unknown: {kind:"qa", title:"پاسخ صادقانه هنگام نبود اطلاعات کافی"},
  qa_followup: {kind:"qa", title:"پاسخگویی و پیگیری درخواست شهروندان"}
});
const reply=(body,status=200)=>new Response(JSON.stringify(body),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff"}});
async function handlePractice(db,user,body){
  if(body?.action==="list"){
    const rows=await db.prepare("SELECT id,exercise_key,kind,response_text,reflection,self_score,duration_seconds,created_at FROM practice_sessions_v1 WHERE telegram_id=? ORDER BY created_at DESC,id DESC LIMIT 100").bind(user.id).all();
    return reply({ok:true,sessions:rows.results||[]});
  }
  if(body?.action==="create"){
    const k=body.exercise_key,ex=Object.hasOwn(PRACTICE_EXERCISES,k)?PRACTICE_EXERCISES[k]:null;
    const response=body.response_text,reflection=body.reflection,score=body.self_score,duration=body.duration_seconds;
    if(!ex||typeof response!=="string"||response.length>3000||typeof reflection!=="string"||reflection.length>1000||
       (response.trim().length<5&&reflection.trim().length<5)||
       !Number.isInteger(score)||score<1||score>5||
       !Number.isInteger(duration)||duration<0||duration>900)return reply({error:"INVALID_PRACTICE"},400);
    const existing=await db.prepare("SELECT COUNT(*) AS n FROM practice_sessions_v1 WHERE telegram_id=?").bind(user.id).first();
    if((existing?.n||0)>=200)return reply({error:"PRACTICE_LIMIT_REACHED"},429);
    const id=crypto.randomUUID();
    await db.batch([
      db.prepare("INSERT INTO candidate_users(telegram_id,display_name,username) VALUES(?,?,?) ON CONFLICT(telegram_id) DO NOTHING").bind(user.id,user.name,user.username),
      db.prepare("INSERT INTO practice_sessions_v1(id,telegram_id,exercise_key,kind,response_text,reflection,self_score,duration_seconds) VALUES(?,?,?,?,?,?,?,?)").bind(id,user.id,k,ex.kind,response,reflection,score,duration)
    ]);
    return reply({ok:true,id},201);
  }
  if(body?.action==="delete"){
    if(typeof body.id!=="string"||!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(body.id))return reply({error:"INVALID_SESSION_ID"},400);
    const r=await db.prepare("DELETE FROM practice_sessions_v1 WHERE id=? AND telegram_id=?").bind(body.id,user.id).run();
    return r.meta?.changes?reply({ok:true}):reply({error:"SESSION_NOT_FOUND"},404);
  }
  return reply({error:"UNKNOWN_ACTION"},400);
}

// Reuse the existing isolated quizzes / quiz_questions / quiz_attempts tables.
// Grade on server only. Never send correct_index before a completed submission.
const quizResponse=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff"}});
const quizIdValid=id=>Number.isSafeInteger(id)&&id>0&&id<100000000;
async function publishedQuiz(db,id){
  return db.prepare("SELECT id,title,description FROM quizzes WHERE id=? AND published=1").bind(id).first();
}
async function quizQuestions(db,quizId){
  const r=await db.prepare("SELECT id,prompt,options_json,correct_index,position FROM quiz_questions WHERE quiz_id=? ORDER BY position,id").bind(quizId).all();
  return r.results||[];
}
function safeOptions(q){
  let options;try{options=JSON.parse(q.options_json)}catch{return null}
  if(!Array.isArray(options)||options.length<2||options.length>8||options.some(x=>typeof x!=="string"||x.length>400)||!Number.isSafeInteger(q.correct_index)||q.correct_index>=options.length||q.correct_index<0)return null;
  return options;
}
function gradeFeedback(q,selected,source){
  const opt=safeOptions(q);
  return {question_id:q.id,prompt:q.prompt,selected_index:selected,correct_index:q.correct_index,is_correct:selected===q.correct_index,correct_answer:opt[q.correct_index],rationale:source?.rationale||"",source_url:source?.source_url||""};
}
async function quizGuidance(db,ids){
  const result=new Map();
  for(const id of ids){
    const r=await db.prepare("SELECT rationale,source_url FROM quiz_guidance_v1 WHERE question_id=?").bind(id).first();
    result.set(id,r||{});
  }
  return result;
}
async function handleQuiz(db,user,b){
  if(b?.action==="catalog"){
    const rows=await db.prepare("SELECT q.id,q.title,q.description,(SELECT COUNT(*) FROM quiz_questions p WHERE p.quiz_id=q.id) AS question_count FROM quizzes q WHERE q.published=1 ORDER BY q.id LIMIT 30").all();
    return quizResponse({ok:true,quizzes:rows.results||[]});
  }
  if(b?.action==="history"){
    const rows=await db.prepare("SELECT a.id AS attempt_id,a.quiz_id,q.title,a.score,a.question_count,a.submitted_at FROM quiz_attempts a JOIN quizzes q ON q.id=a.quiz_id WHERE a.telegram_id=? ORDER BY a.submitted_at DESC,a.id DESC LIMIT 50").bind(user.id).all();
    return quizResponse({ok:true,attempts:rows.results||[]});
  }
  if(b?.action==="review"){
    if(typeof b.attempt_id!=="string"||!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(b.attempt_id))return quizResponse({error:"INVALID_ATTEMPT_ID"},400);
    const previous=await db.prepare("SELECT a.quiz_id,a.answers_json,a.score,a.question_count,a.submitted_at,q.title FROM quiz_attempts a JOIN quizzes q ON q.id=a.quiz_id WHERE a.id=? AND a.telegram_id=?").bind(b.attempt_id,user.id).first();
    if(!previous)return quizResponse({error:"ATTEMPT_NOT_FOUND"},404);
    const questions=await quizQuestions(db,previous.quiz_id);
    let answers;try{answers=JSON.parse(previous.answers_json)}catch{return quizResponse({error:"ATTEMPT_DATA_INVALID"},503)}
    if(!answers||typeof answers!=="object"||Array.isArray(answers))return quizResponse({error:"ATTEMPT_DATA_INVALID"},503);
    const guidance=await quizGuidance(db,questions.map(q=>q.id));
    const feedback=questions.filter(q=>safeOptions(q)).map(q=>gradeFeedback(q,answers[String(q.id)],guidance.get(q.id)));
    return quizResponse({ok:true,quiz_id:previous.quiz_id,title:previous.title,score:previous.score,question_count:previous.question_count,submitted_at:previous.submitted_at,feedback});
  }
  if(!quizIdValid(b?.quiz_id))return quizResponse({error:"INVALID_QUIZ_ID"},400);
  const quiz=await publishedQuiz(db,b.quiz_id);
  if(!quiz)return quizResponse({error:"QUIZ_NOT_FOUND"},404);
  const questions=await quizQuestions(db,b.quiz_id);
  if(questions.length<2||questions.length>20)return quizResponse({error:"QUIZ_NOT_READY"},503);
  const optionLists=questions.map(safeOptions);
  if(optionLists.some(x=>x===null))return quizResponse({error:"QUIZ_NOT_READY"},503);
  if(b.action==="start"){
    return quizResponse({ok:true,quiz,questions:questions.map((q,i)=>({id:q.id,prompt:q.prompt,options:optionLists[i],position:q.position}))});
  }
  if(b.action!=="submit")return quizResponse({error:"UNKNOWN_ACTION"},400);
  const answers=b.answers;
  if(!answers||typeof answers!=="object"||Array.isArray(answers))return quizResponse({error:"INVALID_ANSWERS"},400);
  const keys=Object.keys(answers);
  if(keys.length!==questions.length||keys.some(k=>!/^[1-9]\d*$/.test(k)))return quizResponse({error:"INVALID_ANSWERS"},400);
  let score=0;
  for(let i=0;i<questions.length;i++){
    const q=questions[i],selected=answers[String(q.id)];
    if(!Number.isSafeInteger(selected)||selected<0||selected>=optionLists[i].length)return quizResponse({error:"INVALID_ANSWERS"},400);
    if(selected===q.correct_index)score++;
  }
  const attempts=await db.prepare("SELECT COUNT(*) AS n FROM quiz_attempts WHERE telegram_id=? AND quiz_id=? AND submitted_at>=datetime('now','-1 day')").bind(user.id,b.quiz_id).first();
  if((attempts?.n||0)>=20)return quizResponse({error:"QUIZ_DAILY_LIMIT"},429);
  const attemptId=crypto.randomUUID();
  await db.batch([
    db.prepare("INSERT INTO candidate_users(telegram_id,display_name,username) VALUES(?,?,?) ON CONFLICT(telegram_id) DO NOTHING").bind(user.id,user.name,user.username),
    db.prepare("INSERT INTO quiz_attempts(id,quiz_id,telegram_id,answers_json,score,question_count) VALUES(?,?,?,?,?,?)").bind(attemptId,b.quiz_id,user.id,JSON.stringify(answers),score,questions.length)
  ]);
  const guidance=await quizGuidance(db,questions.map(q=>q.id));
  return quizResponse({ok:true,attempt_id:attemptId,score,question_count:questions.length,feedback:questions.map(q=>gradeFeedback(q,answers[String(q.id)],guidance.get(q.id)))},201);
}

// Read-only learning and task progress for the signed Telegram owner.
// Counts are raw activity metrics, not claims about candidate quality or voter behavior.
const progressResponse=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff"}});
const safeNumber=value=>Number.isFinite(Number(value))?Number(value):0;
async function handleProgress(db,user,body){
  if(body?.action!=="overview")return progressResponse({error:"UNKNOWN_ACTION"},400);
  const id=user.id;
  const [profile,goals,calendar,practice,quizzes,availableQuizzes]=await Promise.all([
    db.prepare("SELECT 1 AS present FROM candidate_profiles WHERE telegram_id=? LIMIT 1").bind(id).first(),
    db.prepare("SELECT COUNT(*) AS total,SUM(CASE WHEN status='done' THEN 1 ELSE 0 END) AS completed,SUM(CASE WHEN status='open' AND target_date IS NOT NULL AND target_date < date('now') THEN 1 ELSE 0 END) AS overdue FROM personal_goals_v2 WHERE telegram_id=?").bind(id).first(),
    db.prepare("SELECT COUNT(*) AS total,SUM(CASE WHEN status='done' THEN 1 ELSE 0 END) AS completed,SUM(CASE WHEN status='scheduled' THEN 1 ELSE 0 END) AS scheduled FROM personal_calendar_v1 WHERE telegram_id=?").bind(id).first(),
    db.prepare("SELECT COUNT(*) AS total,SUM(CASE WHEN kind='speech' THEN 1 ELSE 0 END) AS speech,SUM(CASE WHEN kind='qa' THEN 1 ELSE 0 END) AS qa,COALESCE(SUM(duration_seconds),0) AS duration_seconds,ROUND(AVG(self_score),1) AS self_rating FROM practice_sessions_v1 WHERE telegram_id=?").bind(id).first(),
    db.prepare("SELECT COUNT(*) AS attempts,COUNT(DISTINCT quiz_id) AS unique_quizzes,COALESCE(SUM(score),0) AS correct_answers,COALESCE(SUM(question_count),0) AS answered_questions FROM quiz_attempts WHERE telegram_id=?").bind(id).first(),
    db.prepare("SELECT COUNT(*) AS n FROM quizzes WHERE published=1 AND id IN (SELECT quiz_id FROM quiz_questions GROUP BY quiz_id HAVING count(*) BETWEEN 2 AND 20)").first()
  ]);
  const totalAnswers=safeNumber(quizzes?.answered_questions);
  return progressResponse({
    ok:true,scope:"authenticated_test_account",generated_at:new Date().toISOString(),
    profile:{completed:Boolean(profile?.present)},
    goals:{total:safeNumber(goals?.total),completed:safeNumber(goals?.completed),overdue:safeNumber(goals?.overdue)},
    calendar:{total:safeNumber(calendar?.total),completed:safeNumber(calendar?.completed),scheduled:safeNumber(calendar?.scheduled)},
    practice:{total:safeNumber(practice?.total),speech:safeNumber(practice?.speech),qa:safeNumber(practice?.qa),duration_seconds:safeNumber(practice?.duration_seconds),self_rating:practice?.self_rating===null||practice?.self_rating===undefined?null:safeNumber(practice.self_rating)},
    quizzes:{attempts:safeNumber(quizzes?.attempts),unique_quizzes:safeNumber(quizzes?.unique_quizzes),available_quizzes:safeNumber(availableQuizzes?.n),correct_answers:safeNumber(quizzes?.correct_answers),answered_questions:totalAnswers,correct_percentage:totalAnswers?Math.round(1000*safeNumber(quizzes?.correct_answers)/totalAnswers)/10:null}
  });
}

// Authenticated content drafts for neutral, factual public information. No auto-publication.
const studioKinds=new Set(['service_update','meeting_notice','fact_correction','civic_education']);
const studioResponse=(obj,status=200)=>new Response(JSON.stringify(obj),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'}});
const studioId=id=>typeof id==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id);
function validDraft(b){
 if(!studioKinds.has(b?.kind)||typeof b?.title!=='string'||b.title.trim().length<3||b.title.length>160||
 typeof b?.body!=='string'||b.body.trim().length<10||b.body.length>4000||
 typeof b?.source_url!=='string'||b.source_url.length>800||
 !['draft','reviewed'].includes(b?.status))return false;
 if(b.source_url){
  try{const u=new URL(b.source_url);if(u.protocol!=='https:'||u.username||u.password||u.hostname.length<4)return false}
  catch{return false}
 }
 return true;
}
async function handleStudio(db,user,b){
 if(b?.action==='list'){
  const q=await db.prepare('SELECT id,kind,title,body,source_url,status,created_at,updated_at FROM public_content_drafts_v1 WHERE telegram_id=? ORDER BY updated_at DESC,id DESC LIMIT 100').bind(user.id).all();
  return studioResponse({ok:true,drafts:q.results||[]});
 }
 if(b?.action==='create'){
  if(!validDraft(b))return studioResponse({error:'INVALID_DRAFT'},400);
  const count=await db.prepare('SELECT COUNT(*) AS n FROM public_content_drafts_v1 WHERE telegram_id=?').bind(user.id).first();
  if((count?.n||0)>=100)return studioResponse({error:'DRAFT_LIMIT_REACHED'},429);
  const id=crypto.randomUUID();
  await db.batch([
   db.prepare('INSERT INTO candidate_users(telegram_id,display_name,username) VALUES(?,?,?) ON CONFLICT(telegram_id) DO NOTHING').bind(user.id,user.name,user.username),
   db.prepare('INSERT INTO public_content_drafts_v1(id,telegram_id,kind,title,body,source_url,status) VALUES(?,?,?,?,?,?,?)').bind(id,user.id,b.kind,b.title.trim(),b.body.trim(),b.source_url,b.status)
  ]);
  return studioResponse({ok:true,id},201);
 }
 if(b?.action==='update'){
  if(!studioId(b.id)||!validDraft(b))return studioResponse({error:'INVALID_DRAFT'},400);
  const q=await db.prepare('UPDATE public_content_drafts_v1 SET kind=?,title=?,body=?,source_url=?,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND telegram_id=?').bind(b.kind,b.title.trim(),b.body.trim(),b.source_url,b.status,b.id,user.id).run();
  return q.meta?.changes?studioResponse({ok:true}):studioResponse({error:'DRAFT_NOT_FOUND'},404);
 }
 if(b?.action==='delete'){
  if(!studioId(b?.id))return studioResponse({error:'INVALID_DRAFT_ID'},400);
  const q=await db.prepare('DELETE FROM public_content_drafts_v1 WHERE id=? AND telegram_id=?').bind(b.id,user.id).run();
  return q.meta?.changes?studioResponse({ok:true}):studioResponse({error:'DRAFT_NOT_FOUND'},404);
 }
 return studioResponse({error:'UNKNOWN_ACTION'},400);
}

// Test-only subscription workflow. NO real payment acceptance, no receipts uploaded, no automatic grants.
// Two approved Telegram admin IDs must be passed through a private secret binding; fail closed otherwise.
const MEMBERSHIP_DEMO_RECEIPT='SIMULATED_NO_FILE';
const MEMBERSHIP_DEMO_PLAN='professional';
const MEMBERSHIP_DEMO_DURATION_DAYS=30;
const membershipReply=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'}});
function demoAdminAllowed(user,env){
 const raw=env?.CANDIDATORY_TEST_ADMIN_IDS;
 if(typeof raw!=='string')return false;
 const ids=raw.split(',').map(x=>x.trim());
 if(ids.length!==2||ids[0]===ids[1]||ids.some(x=>!/^[1-9][0-9]{4,18}$/.test(x)))return false;
 return ids.includes(String(user.id));
}
function demoRequestId(value){
 return typeof value==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value);
}
async function handleMembership(db,user,body,env={}){
 const admin=demoAdminAllowed(user,env);
 if(body?.action==='status'){
  const sub=await db.prepare("SELECT plan_id,status,expires_at,source,CASE WHEN plan_id='professional' AND status='active' AND expires_at>datetime('now') THEN 'professional' ELSE 'free' END AS effective_plan FROM candidate_subscriptions_v2 WHERE telegram_id=?").bind(user.id).first();
  const req=await db.prepare("SELECT id,plan_id,reference,status,created_at,reviewed_at FROM manual_payment_requests_v2 WHERE telegram_id=? AND receipt_file_id=? ORDER BY created_at DESC,id DESC LIMIT 10").bind(user.id,MEMBERSHIP_DEMO_RECEIPT).all();
  return membershipReply({ok:true,mode:'isolated_demo_no_real_payment',is_admin:admin,plan:sub?.effective_plan||'free',subscription:sub||null,requests:req.results||[],price_toman:6900000,duration_days:MEMBERSHIP_DEMO_DURATION_DAYS,receipt_upload_available:false,real_payments_enabled:false});
 }
 if(body?.action==='demo_request'){
  const pending=await db.prepare("SELECT id FROM manual_payment_requests_v2 WHERE telegram_id=? AND receipt_file_id=? AND status='pending' LIMIT 1").bind(user.id,MEMBERSHIP_DEMO_RECEIPT).first();
  if(pending)return membershipReply({error:'DEMO_REQUEST_ALREADY_PENDING'},409);
  const lastDay=await db.prepare("SELECT COUNT(*) AS n FROM manual_payment_requests_v2 WHERE telegram_id=? AND receipt_file_id=? AND created_at>=datetime('now','-1 day')").bind(user.id,MEMBERSHIP_DEMO_RECEIPT).first();
  if((lastDay?.n||0)>=3)return membershipReply({error:'DEMO_REQUEST_LIMIT'},429);
  const id=crypto.randomUUID(),reference='DEMO-'+crypto.randomUUID().slice(0,12).toUpperCase();
  try{
   await db.batch([
    db.prepare("INSERT INTO candidate_users(telegram_id,display_name,username) VALUES(?,?,?) ON CONFLICT(telegram_id) DO NOTHING").bind(user.id,user.name,user.username),
    db.prepare("INSERT INTO manual_payment_requests_v2(id,telegram_id,plan_id,reference,receipt_file_id,status) VALUES(?,?,'professional',?,?,'pending')").bind(id,user.id,reference,MEMBERSHIP_DEMO_RECEIPT)
   ]);
  }catch{return membershipReply({error:'DEMO_REQUEST_CONFLICT'},409)}
  return membershipReply({ok:true,id,reference,status:'pending',note:'DEMONSTRATION_ONLY_NO_PAYMENT'},201);
 }
 if(!admin)return membershipReply({error:'ADMIN_ACCESS_DENIED'},403);
 if(body?.action==='admin_queue'){
  const q=await db.prepare("SELECT id,telegram_id,plan_id,reference,status,created_at FROM manual_payment_requests_v2 WHERE receipt_file_id=? AND status='pending' ORDER BY created_at DESC,id DESC LIMIT 50").bind(MEMBERSHIP_DEMO_RECEIPT).all();
  return membershipReply({ok:true,requests:q.results||[],mode:'isolated_demo_only'});
 }
 if(body?.action==='admin_decide'){
  if(!demoRequestId(body.id)||!['approved','rejected'].includes(body.decision))return membershipReply({error:'INVALID_DECISION'},400);
  const request=await db.prepare("SELECT id,telegram_id,status,receipt_file_id FROM manual_payment_requests_v2 WHERE id=? AND receipt_file_id=? LIMIT 1").bind(body.id,MEMBERSHIP_DEMO_RECEIPT).first();
  if(!request)return membershipReply({error:'REQUEST_NOT_FOUND'},404);
  if(request.status!=='pending')return membershipReply({error:'REQUEST_ALREADY_REVIEWED'},409);
  const statements=[
    db.prepare("UPDATE manual_payment_requests_v2 SET status=?,admin_id=?,reviewed_at=CURRENT_TIMESTAMP WHERE id=? AND status='pending' AND receipt_file_id=?").bind(body.decision,user.id,body.id,MEMBERSHIP_DEMO_RECEIPT)
  ];
  if(body.decision==='approved'){
    statements.push(db.prepare("INSERT INTO candidate_subscriptions_v2(telegram_id,plan_id,status,expires_at,source,updated_at) VALUES(?,'professional','active',datetime('now','+30 days'),'admin',CURRENT_TIMESTAMP) ON CONFLICT(telegram_id) DO UPDATE SET plan_id='professional',status='active',expires_at=excluded.expires_at,source='admin',updated_at=CURRENT_TIMESTAMP").bind(request.telegram_id));
  }
  statements.push(db.prepare("INSERT INTO admin_audit(id,workspace_id,actor_id,action,record_type,record_id,detail) VALUES(?,NULL,?,?,?,?,?)").bind(body.id,user.id,body.decision==='approved'?'demo_approve':'demo_reject','demo_request',body.id,'ISOLATED_TEST_NO_REAL_PAYMENT'));
  try{const result=await db.batch(statements);
    if(result[0]?.meta?.changes!==1)return membershipReply({error:'REQUEST_ALREADY_REVIEWED'},409);
  }catch{return membershipReply({error:'DECISION_CONFLICT'},409)}
  return membershipReply({ok:true,status:body.decision,mode:'isolated_demo_no_payment'});
 }
 return membershipReply({error:'UNKNOWN_ACTION'},400);
}

const json=(obj,status=200)=>new Response(JSON.stringify(obj),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff","referrer-policy":"no-referrer"}});
const enc=new TextEncoder();
const hex=b=>[...new Uint8Array(b)].map(n=>n.toString(16).padStart(2,"0")).join("");
async function telegramUser(initData,token,trace={}){
  const fail=(reason)=>{trace.reason=reason;return null};
  if(typeof initData!=="string"||initData.length<30||initData.length>8192||!token)return fail("MISSING_OR_INVALID_INIT_DATA");
  const p=new URLSearchParams(initData);
  if([...p.keys()].length!==new Set(p.keys()).size||!p.has("hash")||!p.has("auth_date")||!p.has("user"))return fail("INVALID_INIT_DATA_FIELDS");
  const expected=p.get("hash");
  if(!/^[a-f0-9]{64}$/i.test(expected))return fail("INVALID_HASH_FORMAT");
  // Bot-token HMAC includes the signature field when Telegram supplies it.
  // Excluding signature applies only to third-party Ed25519 verification.
  p.delete("hash");
  const check=[...p.entries()].sort(([a],[b])=>a<b?-1:a>b?1:0).map(([k,v])=>k+"="+v).join("\n");
  const key=await crypto.subtle.importKey("raw",enc.encode("WebAppData"),{name:"HMAC",hash:"SHA-256"},false,["sign"]);
  const secret=await crypto.subtle.sign("HMAC",key,enc.encode(token));
  const signing=await crypto.subtle.importKey("raw",secret,{name:"HMAC",hash:"SHA-256"},false,["sign"]);
  const actual=hex(await crypto.subtle.sign("HMAC",signing,enc.encode(check)));
  let difference=0;for(let i=0;i<64;i++)difference|=actual.charCodeAt(i)^expected.toLowerCase().charCodeAt(i);
  if(difference)return fail("SIGNATURE_MISMATCH");
  const auth=Number(p.get("auth_date")),now=Math.floor(Date.now()/1000);
  if(!Number.isSafeInteger(auth)||auth>now+60||now-auth>3600)return fail("AUTH_DATE_EXPIRED");
  let user;try{user=JSON.parse(p.get("user"))}catch{return fail("INVALID_USER_JSON")}
  if(!Number.isSafeInteger(user?.id)||user.id<=0)return fail("INVALID_USER_ID");
  return {id:user.id,name:typeof user.first_name==="string"?user.first_name.slice(0,100):"",username:typeof user.username==="string"?user.username.slice(0,100):null};
}
